def merge(ranges):
    """Join overlapping and neighbouring closed integer ranges."""
    merged = []
    for start, end in sorted(ranges):
        if start > end:
            raise ValueError("range start exceeds end")
        if merged and start <= merged[-1][1] + 1:
            left, right = merged[-1]
            merged[-1] = (left, max(right, end))
        else:
            merged.append((start, end))
    return merged


def subtract(ranges, holes):
    """Return the merged ranges left after removing holes."""
    sources = merge(ranges)
    gaps = merge(holes)
    result = []
    i = 0
    for start, end in sources:
        while i < len(gaps) and gaps[i][0] <= end:
            left, right = gaps[i]
            if start < left:
                result.append((start, left - 1))
            start = max(start, right + 1)
            if right >= end:
                break  # This hole may also cover the next source.
            i += 1
        if start <= end:
            result.append((start, end))
    return result


def count(ranges):
    """Count distinct integers, including both endpoints."""
    return sum(end - start + 1 for start, end in merge(ranges))
